const routes=['/','/education-skills','/projects','/personal-projects'];let lang=localStorage.getItem('portfolio-language')==='en'?'en':'vi';let filter=0;let homeCategory=0;let activeProject=null;let returnFocus=null;const $=s=>document.querySelector(s),E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const tags=a=>`<div class="tags">${a.map(x=>`<span class="tag">${E(x)}</span>`).join('')}</div>`;const t=()=>CONTENT[lang];const route=()=>routes.includes(location.pathname.replace(/\/$/,'')||'/')?location.pathname.replace(/\/$/,'')||'/':'/';const navLink=(p,label,cls='')=>`<a href="${p}" data-route class="${cls}">${label}</a>`;
function header(d){return `<header><div class="header-inner">${navLink('/','<span class="brandmark">w.</span><span>MY PORTFOLIO</span>','brand')}<nav id="navigation">${d.nav.map((n,i)=>navLink(routes[i],E(n),route()===routes[i]?'active':'')).join('')}</nav><div class="header-actions"><div class="lang-switch"><button class="lang ${lang==='vi'?'active':''}" data-lang="vi" aria-pressed="${lang==='vi'}">VI</button><span class="note">/</span><button class="lang ${lang==='en'?'active':''}" data-lang="en" aria-pressed="${lang==='en'}">EN</button></div><button class="header-cv card-link" data-action="cv">${d.cv} ↗</button><button class="menu-toggle" aria-label="${lang==='vi'?'Mở menu':'Open menu'}" aria-expanded="false" aria-controls="navigation">☰</button></div></div></header>`}
function footer(d){return `<footer class="site-footer"><div class="wrap footer-grid"><div class="footer-profile"><a class="footer-brand" href="/" data-route><span class="footer-monogram personal-logo"><img src="/assets/personal-logo.png" alt=""></span><span>${d.name}</span></a><div class="footer-social"><button data-action="linkedin" aria-label="LinkedIn">in</button><button data-action="email" aria-label="${d.email}">✉</button></div></div><div class="footer-nav"><h3>${d.footerNavigation}</h3>${d.nav.map((n,i)=>navLink(routes[i],E(n))).join('')}</div><div class="footer-contact"><h3>${d.footerContact}</h3><div class="footer-detail"><span class="footer-icon">✉</span><div><span class="footer-label">E-MAIL</span>${d.emailValue?`<a href="mailto:${E(d.emailValue)}">${E(d.emailValue)}</a>`:`<span class="footer-placeholder">${d.pending}</span>`}</div></div><div class="footer-detail"><span class="footer-icon">⌖</span><div><span class="footer-label">${d.footerLocation}</span><span class="footer-placeholder">${E(d.locationValue)||d.pending}</span></div></div></div></div><div class="wrap footer-bottom"><span>© ${new Date().getFullYear()} ${d.name}</span><span>${d.footer}</span></div></footer>`}

function card(p,d){return `<article class="project-card"><button class="image-link" data-project="${p.id}" aria-label="${E(d.detail+' — '+p.name)}" style="display:block;border:0;padding:0;width:100%">${p.image?`<img class="project-img" src="${p.image}" alt="${E(p.name)}">`:`<div class="project-img text-cover"><span>PRODUCT DEVELOPMENT</span><strong>Photobooth<br>App</strong><span>FEATURES · PRODUCTS · EXPERIENCES</span></div>`}</button><div class="card-body"><span class="card-category">${p.type}</span><h3>${p.name}</h3><div class="meta">${p.role}${p.company?` · ${E(p.company)}`:''}<br>${p.time}</div><p>${p.desc}</p>${tags(p.tags)}<button class="card-link" data-project="${p.id}">${d.detail}<span class="arrow">↗</span></button></div></article>`}
function heading(n,title,desc,action=''){return `<div class="section-head"><div><span class="overline">${n}</span><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`}
function contact(d){return `<div class="contact"><div><h2>${d.contact}</h2><p>${d.contactText}</p><span class="note">${d.contactNote}</span></div><div class="buttons"><button class="btn light" data-action="email">${d.email} · ${E(d.emailValue)} ↗</button><button class="btn secondary" data-action="linkedin">${d.linkedin} ↗</button></div></div>`}
function home(d){return `<main class="wrap"><section class="hero reveal"><div><div class="eyebrow">${d.eyebrow}</div><h1 class="hero-name">${(d.nameLines||[d.name]).map(line=>`<span>${E(line)}</span>`).join('')}</h1><p class="hero-role">${d.role}</p><p class="intro">${d.intro}</p><div class="buttons">${navLink('/projects',d.view+' <span>↗</span>','btn')}<button class="btn secondary" data-action="cv">${d.cv} ↓</button></div><div class="philosophy"><span class="overline">${d.philosophy}</span><p class="quote">${d.quote}</p>${d.quoteNote?`<span class="note">${d.quoteNote}</span>`:''}</div></div><figure class="portrait-block portrait-editorial"><div class="portrait"><img src="/assets/portrait.png" alt="${E(d.name)}" class="portrait-photo" fetchpriority="high"></div><figcaption class="portrait-caption"><span>${d.name}</span><span>${d.role}</span></figcaption></figure></section><section class="section">${journeyDashboard(d)}<h3 class="values-title">${d.values}</h3><div class="values">${d.valueTitles.map((x,i)=>`<div class="value"><div class="num">0${i+1} /</div><h3>${x}</h3><p>${d.valueTexts[i]}</p></div>`).join('')}</div></section><section class="section">${heading('02 / '+d.pageLabel[2],d.featured,d.featuredSub,navLink('/projects',d.all+' ↗','text-link'))}${featuredSelector(d)}</section><section class="section">${heading('03 / CAREER ROADMAP',d.roadmap,d.roadSub)}<div class="roadmap"><article class="road-card"><span class="overline">${d.short}</span><h3>${d.shortRole}</h3><h4>${d.goalsLabel}</h4><ul class="road-goals">${d.goalItems.map(x=>`<li>${E(x)}</li>`).join('')}</ul><h4>${d.focusLabel}</h4>${tags(d.shortTags)}</article><article class="road-card"><span class="overline">${d.long}</span><h3>${d.longRole}</h3><p>${d.longText}</p><h4>${d.growthLabel}</h4>${tags(d.longTags)}</article></div></section>${contact(d)}</main>`}
function featuredSelector(d){return `<div class="experience-selector" role="group" aria-label="${d.featured}">${d.experienceTypes.map((title,i)=>`<button type="button" class="experience-option ${homeCategory===i?'selected':''}" data-home-category="${i}" aria-pressed="${homeCategory===i}"><span class="experience-label">${title}</span>${lang==='vi'?`<span class="experience-english">${d.experienceTypeEnglish[i]}</span>`:''}<span class="experience-description">${d.experienceTypeDescriptions[i]}</span></button>`).join('')}</div><div class="experience-placeholder" aria-live="polite"><span>0${homeCategory+1} / ${d.experienceTypeEnglish[homeCategory]}</span><p>${d.experienceEmpty[homeCategory]}</p></div>`}
function intro(d,i,title,desc){return `<div class="page-intro reveal"><span class="eyebrow">${d.pageLabel[i]}</span><h1>${title}</h1><p>${desc}</p><span class="sample-label">${d.sample}</span></div>`}
function education(d){return `<main class="wrap education-page"><div class="page-intro reveal"><span class="eyebrow">${d.pageLabel[1]}</span><h1>${d.eduTitle}</h1></div><section class="education-grid page-content"><article class="panel"><span class="overline">01 / ${d.education}</span><h2 class="university-name">${d.school}</h2><h3 class="degree">${d.major}</h3><span class="gpa">${d.gpa}</span><div class="coursework"><h3>${d.courses}</h3><div class="course-list">${d.courseItems.map(c=>`<span class="tag">${E(c)}</span>`).join('')}</div></div></article><article class="panel scholarship-panel"><span class="overline">${d.scholar}</span><div class="scholarship-symbol" aria-hidden="true">✦</div><h3>${d.scholarText}</h3><p>${d.scholarPeriod}</p></article></section><section class="section certifications-section">${heading('02 / CERTIFICATIONS',d.cert,'')}<div class="certification-list">${d.certifications.map(c=>`<article class="certification-row"><span class="cert-year">${c.year}</span><div><h3>${E(c.title)}</h3>${c.issuer?`<p>${E(c.issuer)}</p>`:''}</div></article>`).join('')}</div></section><section class="section">${heading('03 / SKILLS',d.skills,'')}<div class="skill-grid approved-skills">${d.skillGroups.map((g,i)=>`<article class="skill-card"><div class="skill-icon">0${i+1}.</div><h3>${E(g.title)}</h3><ul>${g.items.map(x=>`<li>${E(x)}</li>`).join('')}</ul></article>`).join('')}</div></section><section class="section">${heading('04 / TOOLS',d.tools,'')}<div class="tool-grid">${d.toolGroups.map((x,i)=>`<div><h3>${x}</h3>${tags(d.toolsLists[i])}</div>`).join('')}</div></section>${contact(d)}</main>`}

function experience(d){const groups=['work','project'];return `<main class="wrap"><div class="page-intro reveal"><span class="eyebrow">${d.pageLabel[2]}</span><h1>${d.expTitle}</h1></div><div class="page-content"><div class="filters">${d.filters.map((x,i)=>`<button class="filter ${filter===i?'active':''}" data-filter="${i}" aria-pressed="${filter===i}">${x}</button>`).join('')}</div>${groups.map((g,i)=>{if(filter!==0&&filter!==i+1)return '';const list=d.projects.filter(p=>p.category===g);return `<section class="experience-group"><h2>${d.experienceHeading[i]}</h2><p>${d.experienceTypeDescriptions[i]}</p>${list.length?`<div class="cards">${list.map(p=>card(p,d)).join('')}</div>`:`<div class="experience-placeholder">${d.experienceEmpty[i]}</div>`}</section>`}).join('')}</div>${contact(d)}</main>`}

function personal(d){return `<main class="wrap">${intro(d,3,d.personalTitle,d.personalSub)}<div class="page-content"><article class="personal-layout"><img src="/assets/personal.svg" alt="${E(d.personalName)}"><div class="card-body"><span class="overline">INDEPENDENT PROJECT / 01</span><h2 style="margin-top:20px">${d.personalName}</h2><p>${d.personalDesc}</p>${tags(['[Tool 1]','[Tool 2]'])}${d.personalUrl?`<a class="btn" href="${E(d.personalUrl)}" target="_blank" rel="noopener noreferrer">${d.visit} ↗</a>`:`<button class="btn" data-action="missing">${d.visit} ↗</button><p class="note" style="margin:12px 0 0">${d.noUrl}</p>`}</div></article></div>${contact(d)}</main>`}
function render(){const d=t();document.body.classList.toggle('about-gray',route()==='/');document.documentElement.lang=lang;document.title=`${d.nav[routes.indexOf(route())]} · ${d.name} | BA Portfolio`;$('#app').innerHTML=header(d)+`<div class="demo">${d.demo}</div>`+({'/':home,'/education-skills':education,'/projects':experience,'/personal-projects':personal}[route()])(d)+footer(d);$('.close').setAttribute('aria-label',d.close)}
function openModal(html,zoom=false){const m=$('#modal');if(!m.open)returnFocus=document.activeElement;m.classList.toggle('zoom-mode',zoom);$('#modal-body').innerHTML=html;if(!m.open)m.showModal();m.scrollTop=0;document.body.classList.add('locked');$('.close').focus()}
function closeModal(){activeProject=null;$('#modal').close();document.body.classList.remove('locked');if(returnFocus?.isConnected)returnFocus.focus()}
function project(id){const d=t(),p=d.projects.find(p=>p.id===id);if(!p)return;activeProject=id;if(p.sections||p.id==='snap-ba'){projectDetails(p,d);return}openModal(`<div class="modal-content"><span class="sample-label">${d.sample}</span><div class="overline">${p.type}</div><h2 style="margin-top:12px">${p.name}</h2><p class="meta">${p.role} · ${p.time}</p>${tags(p.tags)}<img class="modal-cover" src="${p.image}" alt="${E(p.name)}"><div class="case-grid">${[[d.context,d.contextText],[d.contribution,d.contributionText],[d.solution,d.solutionText],[d.result,d.resultText]].map(x=>`<div class="panel"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div><h3 style="margin-top:35px">${d.gallery}</h3><p class="note">${d.galleryNote}</p><div class="gallery">${(PROJECT_MEDIA[id]||[]).map((src,i)=>`<button data-zoom="${src}" aria-label="${E(d.zoom)} ${i+1}"><img src="${src}" alt="${E(p.name)} — ${i+1}"></button>`).join('')}</div><button class="btn secondary" style="margin-top:25px" data-action="list">← ${d.back}</button></div>`)}
function action(a){const d=t();if(a==='list'){closeModal();return}if(a==='back'){project(activeProject);return}if(a==='cv'&&d.cvUrl){window.open(d.cvUrl,'_blank','noopener,noreferrer');return}if(a==='email'&&d.emailValue){location.href='mailto:'+d.emailValue;return}if(a==='linkedin'&&d.linkedinUrl){window.open(d.linkedinUrl,'_blank','noopener,noreferrer');return}openModal(`<div class="modal-content notice"><span class="sample-label">${d.sample}</span><h2>${a==='cv'?d.cvTitle:d.missingTitle}</h2><p>${a==='cv'?d.cvText:d.missingText}</p></div>`)}
document.addEventListener('click',e=>{let el=e.target.closest('[data-route]');if(el&&!e.metaKey&&!e.ctrlKey){e.preventDefault();history.pushState({},'',el.getAttribute('href'));filter=0;render();window.scrollTo(0,0);return}el=e.target.closest('[data-lang]');if(el){lang=el.dataset.lang;localStorage.setItem('portfolio-language',lang);filter=0;render();return}el=e.target.closest('[data-home-category]');if(el){homeCategory=Number(el.dataset.homeCategory);const pos=window.scrollY;render();window.scrollTo(0,pos);document.querySelector(`[data-home-category="${homeCategory}"]`).focus({preventScroll:true});return}el=e.target.closest('[data-project]');if(el){project(el.dataset.project);return}el=e.target.closest('[data-filter]');if(el){filter=Number(el.dataset.filter);let pos=window.scrollY;render();window.scrollTo(0,pos);return}el=e.target.closest('[data-action]');if(el){action(el.dataset.action);return}el=e.target.closest('[data-zoom]');if(el){const d=t();openModal(`<div class="modal-content"><button class="text-link" data-action="back">← ${d.back}</button><p class="note">${d.zoomHint}</p><div class="zoom-scroll"><img class="zoom-image" src="${el.dataset.zoom}" alt="${E(d.gallery)}"></div></div>`,true);return}if(e.target.closest('.menu-toggle')){let open=$('nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open)}if(e.target.closest('.close'))closeModal();if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});window.addEventListener('popstate',()=>{filter=0;render();window.scrollTo(0,0)});render();

function projectDetails(p,d){if(p.id==='photobooth-product'){photoboothDetails(p,d);return}openModal(`<div class="modal-content approved-case"><div class="overline">${E(p.type)}</div><h2>${E(p.name)}</h2><p class="meta">${E(p.detailRole||p.role)} · ${E(p.company)}<br>${E(p.time)}</p>${tags(p.tags)}<div class="project-facts">${p.facts.map(f=>`<p>${E(f)}</p>`).join('')}</div>${(p.images||(p.image?[p.image]:[])).map((src,i)=>`<button class="case-cover-button" data-zoom="${src}" aria-label="${E(d.zoom)} ${i+1}"><img class="modal-cover" src="${src}" alt="${E(p.name)} — ${i+1}"><span>${d.zoom} ${i+1} ↗</span></button>`).join('')}${p.sections.map((s,i)=>`<section class="case-section"><span class="overline">0${i+1}</span><h3>${E(s.title)}</h3>${s.text?`<p>${E(s.text)}</p>`:''}${s.items?`<ul>${s.items.map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:''}</section>`).join('')}<button class="btn secondary" data-action="list">← ${d.back}</button></div>`)}

function photoboothDetails(p,d){
 const vi=lang==='vi',items=p.sections[1].items;
 const groups=vi?['Nghiên cứu & định hướng sản phẩm','Phát triển tính năng & trải nghiệm','Phối hợp & theo dõi triển khai']:['Research & product direction','Features & experiences','Coordination & delivery support'];
 const labels=vi?['Chỉnh sửa khuôn mặt','Bộ lọc màu','Cá nhân hóa merchandise']:['Facial editing','Color filters','Merchandise personalization'];
 const details=vi?['Làm mịn da, cân chỉnh tông màu và độ sáng, tinh chỉnh đường nét và khuyết điểm nhỏ.','Phát triển bộ lọc theo phong cách Retro và Y2K.','Đưa ảnh Photobooth lên áo hoodie, áo phông, ốp điện thoại, túi và bình giữ nhiệt.']:['Skin smoothing, skin tone and brightness adjustments, facial refinement, and minor blemish removal.','Filters inspired by Retro and Y2K styles.','Photobooth photos on hoodies, T-shirts, phone cases, bags, and insulated bottles.'];
 openModal(`<div class="modal-content approved-case photobooth-case"><div class="overline">${E(p.type)}</div><h2>${E(p.name)}</h2><p class="meta">${E(p.detailRole)} · ${E(p.company)}<br>${E(p.time)}</p>${tags(p.tags)}<div class="project-facts">${p.facts.map(f=>`<p>${E(f)}</p>`).join('')}</div><section class="case-section"><span class="overline">01</span><h3>${E(p.sections[0].title)}</h3><p>${E(p.sections[0].text)}</p></section><section class="case-section contributions"><span class="overline">02</span><h3>${E(p.sections[1].title)}</h3><div class="contribution-groups">${[[0,1],[2,3,4,5],[6]].map((ids,i)=>`<article class="contribution-group"><h4><span>0${i+1}</span>${groups[i]}</h4><ul>${ids.map(n=>`<li>${E(items[n])}</li>`).join('')}</ul></article>`).join('')}</div><div class="photobooth-gallery">${p.images.map((src,i)=>`<button class="case-cover-button" data-zoom="${src}" aria-label="${E(d.zoom)} ${i+1}"><img src="${src}" alt="${i===0?'Photobooth merchandise':'Photobooth concepts'}"><span>${i===0?(vi?'Sản phẩm merchandise':'Merchandise products'):(vi?'Concept & trải nghiệm':'Concepts & experiences')} · ${d.zoom} ↗</span></button>`).join('')}</div></section><section class="case-section achievements"><span class="overline">03</span><h3>${E(p.sections[2].title)}</h3><div class="achievement-intro"><strong>03</strong><p>${vi?'nhóm tính năng đã tham gia phát triển':'Contributed to three feature areas'}</p></div><div class="achievement-grid">${labels.map((label,i)=>`<article><span class="overline">0${i+1}</span><h4>${label}</h4><p>${details[i]}</p></article>`).join('')}</div><p class="concept-outcome">${vi?'Đồng thời tham gia xây dựng các concept trải nghiệm Photobooth riêng.':'Also contributed to distinct Photobooth experience concepts.'}</p></section><button class="btn secondary" data-action="list">← ${d.back}</button></div>`)
}

function journeyDashboard(d){const vi=lang==='vi';const labels=['DELIVERABLE','MODELING','PROTOTYPING','AGILE BACKLOG'];const descriptions=vi?['Tài liệu yêu cầu nghiệp vụ & đặc tả hệ thống','Sơ đồ hóa & tối ưu quy trình luồng vận hành','Bản vẽ cấu trúc giao diện tương tác người dùng','Kịch bản người dùng chuẩn hóa tiêu chí Acceptance']:[];const paths=['<path d="M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6"/>','<path d="M3 4h6v6H3z M15 3h6v6h-6z M15 15h6v6h-6z M9 7h3v11h3 M12 6h3"/>','<path d="M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M18 14v8 M14 18h8"/>','<path d="M21 11a9 9 0 1 1-5-8 M7 11l4 4L21 4"/>'];return `<div class="journey-dashboard"><div class="journey-heading"><div><span class="journey-kicker">↗ ${vi?'HÀNH TRÌNH THỰC THI':'PROJECT JOURNEY'}</span><h2>${vi?'Hành trình dự án & Năng lực tạo tác':d.overview}</h2></div>${vi?'<p>Tổng hợp số liệu bàn giao tài liệu kỹ thuật<br>& giải pháp nghiệp vụ thực chiến</p>':''}</div><div class="journey-cards">${d.metrics.map((m,i)=>`<article class="journey-stat"><div class="journey-card-top"><span class="journey-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[i]}</svg></span><span class="journey-badge">${labels[i]}</span></div><strong>${d.metricValues[i]}</strong><h3>${E(m)}</h3>${descriptions[i]?`<p>${descriptions[i]}</p>`:''}</article>`).join('')}</div></div>`}
